// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    address owner;

    function setUp() public {
        c = new DepositLog();
    }

    function testFuzz_property(address logger, bool status) public {
        bool ok;
        vm.prank(address(0));
        try c.setApprovedLogger(logger, status) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            bool stored = c.approvedLoggers(logger);
            assertTrue(stored == status);
        } else {
            assertTrue(true);
        }
    }
}
